// ----- big surf wave (curling wall) -----
const waveGroup = new THREE.Group();
scene.add(waveGroup);

function buildWaveWall() {
  // Cylinder segment forming a curling wall along Z axis (length along Z)
  // Radius 4, height 32 along Y of cylinder -> we rotate to align along Z
  const r = 4.2;
  const geo = new THREE.CylinderGeometry(r, r, 32, 48, 1, true, Math.PI * 0.15, Math.PI * 0.85);
  // Cylinder Y axis is length; we want length along Z, so rotate X 90
  geo.rotateX(Math.PI / 2);
  // After rotation, now length along Z, curved around X-Y plane. Need to shape to be curling over.
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    // x is roughly radial in original, y is length
    // We have rotated, so interpret: keep as is, but lift bottom and push crest forward (+X)
    // Add taper: near ends, lower height
    const t = (z + 16) / 32; // 0..1 along length
    const taper = Math.sin(t * Math.PI); // peak middle
    const lift = taper * 0.6;
    y = y * 0.92 + lift * 1.2;
    // curl: push top forward (+X) proportional to y
    const curl = Math.max(0, (y + 1) / 5) * 1.1;
    x = x * 1.05 + curl * 0.85;
    // add slight undulation
    x += Math.sin(z * 0.35) * 0.12;
    pos.setXYZ(i, x, y, z);
  }
  geo.computeVertexNormals();
  return geo;
}

const waveWallGeo = buildWaveWall();
const waveMat = new THREE.MeshPhysicalMaterial({
  color: 0x0e8fb5,
  roughness: 0.22,
  metalness: 0.02,
  transmission: 0.22,
  thickness: 1.2,
  transparent: true,
  opacity: 0.94,
  clearcoat: 0.7,
  clearcoatRoughness: 0.25,
  side: THREE.DoubleSide
});
const waveWall = new THREE.Mesh(waveWallGeo, waveMat);
waveWall.position.set(-3.2, 1.4, 0);
waveWall.castShadow = true; waveWall.receiveShadow = true;
waveGroup.add(waveWall);

// inner shadow side of wave (darker)
const waveInnerGeo = buildWaveWall();
const waveInner = new THREE.Mesh(waveInnerGeo, new THREE.MeshStandardMaterial({
  color: 0x065f7a, roughness: 0.45, metalness: 0, transparent: true, opacity: 0.55, side: THREE.BackSide
}));
waveInner.position.copy(waveWall.position);
waveGroup.add(waveInner);

// foam crest: tube along top edge
{
  const crestPts = [];
  for (let t = -14; t <= 14; t += 0.9) {
    const tap = Math.sin((t+16)/32*Math.PI);
    // top edge y approx: after build, crest y ~ 3.2 peak
    const y = 3.8 + tap*0.7 + Math.sin(t*0.4)*0.18;
    const x = -3.2 + 3.6 + tap*0.6 + Math.sin(t*0.28)*0.14;
    crestPts.push(new THREE.Vector3(x, y, t));
  }
  const curve = new THREE.CatmullRomCurve3(crestPts);
  const tubeGeo = new THREE.TubeGeometry(curve, 48, 0.42, 10, false);
  const foamMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35, metalness: 0, transparent: true, opacity: 0.95, emissive: 0x222222 });
  const foam = new THREE.Mesh(tubeGeo, foamMat);
  foam.castShadow = false; foam.receiveShadow = true;
  waveGroup.add(foam);

  // secondary foam lip
  const lipPts = crestPts.map(p => new THREE.Vector3(p.x - 0.5, p.y - 0.8, p.z));
  const lipCurve = new THREE.CatmullRomCurve3(lipPts);
  const lipTube = new THREE.TubeGeometry(lipCurve, 48, 0.28, 8, false);
  const lip = new THREE.Mesh(lipTube, new THREE.MeshStandardMaterial({ color: 0xeaf7ff, roughness: 0.5, transparent: true, opacity: 0.85 }));
  waveGroup.add(lip);
}

