+    const y0 = pos.getY(i); // -3 .. 3
+    const z = pos.getZ(i);  // -15 .. 15
+    const v = (y0 + 3) / 6; // 0 bottom .. 1 top
+    const t = (z + 15) / 30;
+    const taper = Math.sin(t * Math.PI); // 0 at ends, 1 middle
+    // curl forward (+X) increases with height
+    const curl = v * v * 1.55 * (0.55 + taper * 0.55);
+    // shape: lean forward at top, slight pocket
+    const x = curl + Math.sin(z * 0.30) * 0.10 * v + Math.sin(z*0.12)*0.06;
+    // height: middle higher
+    const y = y0 * 0.88 + 0.3 + (taper - 0.2) * 0.55 + Math.sin(z*0.22)*0.07;
+    pos.setXYZ(i, x, y, z);
+  }
+  geo.computeVertexNormals();
+  return geo;
