import puppeteer from "puppeteer-core";
import { createServer } from "http";
import { readFile } from "fs/promises";
import path from "path";
import { fileURLToPath } from "url";
import { execSync } from "child_process";
import { existsSync } from "fs";
const __dirname = path.dirname(fileURLToPath(import.meta.url));
execSync("npx esbuild main.js --bundle --format=esm --outfile=bundle.js --log-level=warning", {cwd:__dirname, stdio:"inherit"});
const viewHtml = (await readFile(path.join(__dirname,"index.html"),"utf8")).replace('src="main.js"','src="bundle.js"');
const mime={".html":"text/html",".js":"text/javascript"};
const server=createServer(async(req,res)=>{
  let p=req.url.split("?")[0]; if(p==="/")p="/view.html"; if(p==="/index.html")p="/view.html";
  const fp=path.join(__dirname,p);
  if(!existsSync(fp)){res.writeHead(404);res.end("nf");return;}
  if(p==="/view.html"){res.writeHead(200,{"Content-Type":"text/html"});res.end(viewHtml);return;}
  const d=await readFile(fp); res.writeHead(200,{"Content-Type":mime[path.extname(fp)]||"application/octet-stream"});res.end(d);
});
await new Promise(r=>server.listen(5174,"127.0.0.1",r));
const chrome="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const browser=await puppeteer.launch({executablePath:chrome, headless:true, args:["--no-sandbox","--enable-unsafe-swiftshader","--use-gl=swiftshader","--disable-dev-shm-usage"]});
const page=await browser.newPage();
page.on("console", m=> console.log(`[console.${m.type()}]`, m.text(), m.location()));
page.on("pageerror", e=> console.log("[pageerror]", e.message, e.stack));
page.on("requestfailed", r=> console.log("[reqfail]", r.url(), r.failure()?.errorText));
await page.setViewport({width:1280,height:800});
await page.goto("http://127.0.0.1:5174/view.html",{waitUntil:"networkidle0"});
await new Promise(r=>setTimeout(r,5000));
await browser.close(); server.close();

